 text('profile','profile.name','Display name',60);text('profile','profile.username','Username',40);text('profile','profile.pronouns','Pronouns',40);text('profile','profile.tagline','Personal greeting',140);text('profile','profile.status','Status',90);add('profile','profile.bio','Biography','textarea',{max:700,default:''});text('profile','profile.interests','Interests',180);text('profile','profile.quote','Profile quote',160,true);text('profile','profile.favoriteGames','Favorite games (comma separated)',500,true);text('profile','profile.anthemTitle','Anthem title',120);text('profile','profile.anthemArtist','Artist / source',120);add('profile','profile.anthemUrl','Anthem link (HTTPS)','url',{default:'',max:1000});add('profile','profile.profileLink','Website (HTTPS)','url',{default:'',max:1000});select('profile','settings.spaceLayout','Profile template',['bento','classic','scrapbook','neon','portfolio'],'bento');select('profile','settings.spaceWallpaper','Profile wallpaper',['nebula','aurora','vaporwave','arcade','dusk'],'nebula');color('profile','settings.spaceAccent','Profile accent','#63e9cd');select('profile','settings.spaceFont','Profile font',['system','serif','mono','rounded'],'system');select('profile','settings.spaceTextAlign','Text alignment',['left','center'],'left',true);number('profile','settings.spaceGlow','Profile glow',0,28,14,true);number('profile','settings.spaceOpacity','Profile surface opacity (%)',55,100,88,true);number('profile','settings.spaceCorner','Profile corner radius',8,36,24,true);select('profile','settings.spaceMotion','Profile motion',['off','subtle','aurora','stars'],'subtle',true);select('profile','settings.rv18.profileEffect','Profile atmosphere',['none','stars','rain','snow'],'none',true);select('profile','settings.rv18.linkStyle','Social link style',['cards','minimal','pills'],'cards',true);
